// Existing marketing, authentication and admin presentation. Local demo only.
function home(){return `<div class="page"><section class="hero"><div><h1>围绕商品资料，<br>完成下一份创作。</h1><p>在一个工作台中，手动选择文案、图片或视频 Agent。准备资料与指令，确认规格和费用，再把结果留在自己的作品库。</p><div class="row"><button class="primary" data-action="register">注册体验</button><button data-action="workspace">查看工作台演示</button></div><p style="font-size:12px;margin:16px 0 0">首版使用试用积分 · 在线充值暂未开放</p></div><div class="hero-demo"><div class="row spread"><strong>从商品资料到创作结果</strong><span class="pill">交互演示</span></div><div class="sample-sheet" style="margin-top:18px"><small>商品资料 / 示例</small><h3>青瓷马克杯</h3><p>350mL · 带杯盖 · 办公室日常饮水</p><div class="sample-lines"><span class="pill">文案 Agent</span><p>把一杯水的时间，留给忙碌日常。<br>350mL 青瓷马克杯，配有杯盖，适合放在办公桌边使用。</p><small>仅展示已提供的商品事实；此处为人工演示文案。</small></div></div><div class="row spread" style="margin-top:18px"><span>规格与费用在生成前确认</span><strong>8 积分 <small>演示值</small></strong></div></div></section><section class="home-section"><h2>三个 Agent，按需要选择</h2><div class="feature-row"><h3>文案创作</h3><p>商品资料与文字要求，整理成通用电商文案。</p><p class="muted">完整文案保存后成为正式作品；流式片段仅用于临时展示。</p></div><div class="feature-row"><h3>图片创作</h3><p>围绕商品图片生成主图、场景图、详情页图片或海报。</p><p class="muted">仅开放接口支持且已确认规则的规格，首版通过整张重新生成修改。</p></div><div class="feature-row"><h3>视频创作</h3><p>用商品介绍与图片准备可播放、下载的视频。</p><p class="muted">时长、比例、声音与字幕按服务能力配置，首版通过整段重新生成修改。</p></div></section><section class="home-section"><h2>真实案例位置</h2><p class="muted">尚未提供获公开展示授权的真实产出。本原型保留案例区域，生产官网需上传真实作品并登记来源、归属和授权依据。</p><div class="notice" style="margin-top:20px">本页展示的资料、文案和视觉样例均为演示内容，不作为真实案例或效果承诺。</div></section><section class="home-section"><h2>从资料到作品，过程看得见</h2><div class="steps"><div><strong>准备商品资料</strong><p class="muted">选择 Agent，上传素材，按需完善创作指令。</p></div><div><strong>确认规格与费用</strong><p class="muted">提交时固定输入和费用，受理后冻结积分。</p></div><div><strong>查看任务与成果</strong><p class="muted">完整成果保存后扣减；确定失败释放；状态不明先核查。</p></div></div><div class="home-footer"><div><h2>开始一次商品创作</h2><p>账号密码注册，无手机号或邮箱验证前置。</p></div><button class="primary" data-action="register">注册体验</button></div></section><footer>暂定品牌与文案 · D-11 确认后方可用于公开官网。</footer></div>`}
function auth(){return `<section class="panel auth"><h1>${authTab==='register'?'注册体验':'欢迎回来'}</h1><p class="muted">使用账号密码，进入你的创作工作台。</p><div class="tabs" role="group" aria-label="登录或注册">${[['login','登录'],['register','注册']].map(([key,label])=>`<button data-action="auth-${key}" class="${authTab===key?'active':''}" aria-pressed="${authTab===key}">${label}</button>`).join('')}</div><form id="auth-form"><div class="field"><label for="username">账号</label><input id="username" autocomplete="username" required minlength="3" placeholder="请输入账号"></div><div class="field"><label for="password">密码</label><input id="password" type="password" autocomplete="${authTab==='register'?'new-password':'current-password'}" required minlength="8" placeholder="至少 8 位（演示规则）"></div>${authTab==='register'?'<div class="field"><label for="password-confirm">确认密码</label><input id="password-confirm" type="password" autocomplete="new-password" required minlength="8"></div>':''}<p id="auth-error" class="danger" role="alert"></p><button type="submit" class="primary">${authTab==='register'?'创建演示账户':'进入演示工作台'}</button></form><p><small>不增加手机号、邮箱验证。赠送积分为演示配置；生产赠送值待 D-05 确认。原型不保存密码。</small></p></section>`}
const adminLabels={tasks:'任务与异常',users:'用户管理',credits:'积分管理',agents:'Agent 配置',specs:'规格与价格',usage:'用量统计',site:'官网内容',logs:'操作日志'};
function adminContent(){return AdminDemo.content(adminTab);}
function admin(){return `<div class="page">${pageHeading('管理后台','独立后台演示：查询任务、维护用户与配置，所有数据仅在本页内存中生效。',`<span class="pill">管理员 admin-demo</span>`)}<div class="admin-layout"><aside class="admin-nav" aria-label="后台模块">${Object.keys(adminLabels).map(k=>`<button class="${adminTab===k?'active':''}" aria-pressed="${adminTab===k}" data-action="admin-${k}">${adminLabels[k]}</button>`).join('')}<p><small>演示环境 · 刷新重置<br>不改变个人创作账户与账本</small></p></aside><section class="panel">${adminContent()}</section></div></div>`;}